after:
:root {
  /* Color scheme */
  color-scheme: dark;

  /* Base palette */
  --bg: #050607;
  --bg2: #080a0d;
  --panel: rgba(14, 17, 22, 0.72);
  --panel2: rgba(19, 23, 30, 0.78);

  /* Lines and strokes */
  --line: rgba(255, 255, 255, 0.095);
  --line2: rgba(255, 255, 255, 0.16);

  /* Text */
  --text: rgba(245, 247, 250, 0.94);
  --muted: rgba(245, 247, 250, 0.55);
  --faint: rgba(245, 247, 250, 0.34);

  /* Accents and semantic tones */
  --accent: #e9ddc4;  /* sand */
  --accent2: #9db8ff; /* sky */
  --good: #91f2bd;
  --warn: #ffd27e;
  --bad: #ff8f8f;

  /* Effects */
  --shadow: 0 24px 90px rgba(0, 0, 0, 0.55);
  --shadow-soft: 0 18px 60px rgba(0, 0, 0, 0.22);
  --blur: blur(24px) saturate(1.2);

  /* Typography */
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  /* Radii */
  --radius-1: 8px;
  --radius-2: 12px;
  --radius-3: 16px;
  --radius-4: 20px;
  --radius-5: 24px;
  --radius-6: 28px;
  --radius-round: 999px;

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 6px;
  --space-3: 8px;
  --space-4: 10px;
  --space-5: 12px;
  --space-6: 14px;
  --space-7: 16px;
  --space-8: 18px;
  --space-9: 22px;
  --space-10: 26px;

  /* Animation */
  --ease-1: cubic-bezier(0.2, 0.7, 0.2, 1);
  --ease-2: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-1: 140ms;
  --dur-2: 220ms;
  --dur-3: 360ms;

  /* Z indices */
  --z-ambient: 0;
  --z-app: 1;
  --z-dock: 12;
  --z-modal: 20;
  --z-overlay: 30;
}

